'use strict';

// MODULES //

var tape = require( 'tape' );
var IS_NODE = require( '@stdlib/assert/is-node' );
var IS_LITTLE_ENDIAN = require( '@stdlib/assert/is-little-endian' );
var gammaincinv = require( './../lib/native.js' );


// VARIABLES //

var FLG = IS_NODE && ( process.platform !== 'win32' || process.arch !== 'ia32' );


// FIXTURES //

var arg1 = require( './fixtures/r/arg1.json' );
var arg2 = require( './fixtures/r/arg2.json' );
var expected_lower = require( './fixtures/r/expected.json' );
var upperArg1 = require( './fixtures/r/upper_arg1.json' );
var upperArg2 = require( './fixtures/r/upper_arg2.json' );
var expected_upper = require( './fixtures/r/upper_expected.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof gammaincinv, 'function', 'main export is a function' );
	t.end();
});

tape( 'if node and not Windows 32-bit, the function is the native function', function test( t ) {
	if ( FLG && IS_LITTLE_ENDIAN ) {
		t.strictEqual( gammaincinv.name, 'gammaincinv', 'function name is `gammaincinv`' );
	} else {
		t.ok( true, 'not node or is Windows 32-bit' );
	}
	t.end();
});

tape( 'the function computes the inverse incomplete gamma function (lower)', function test( t ) {
	var expected;
	var actual;
	var p;
	var a;
	var i;

	p = arg1;
	a = arg2;

	for ( i = 0; i < p.length; i++ ) {
		actual = gammaincinv( p[i], a[i], false );
		t.inDelta( actual, expected_lower[i], 1e-12, 'p: ' + p[i] + ', a: ' + a[i] + '. Actual: ' + actual + '. Expected: ' + expected_lower[i] + '.' );
	}
	t.end();
});

tape( 'the function computes the inverse incomplete gamma function (upper)', function test( t ) {
	var actual;
	var p;
	var a;
	var i;

	p = upperArg1;
	a = upperArg2;

	for ( i = 0; i < p.length; i++ ) {
		actual = gammaincinv( p[i], a[i], true );
		t.inDelta( actual, expected_upper[i], 1e-12, 'p: ' + p[i] + ', a: ' + a[i] + '. Actual: ' + actual + '. Expected: ' + expected_upper[i] + '.' );
	}
	t.end();
});
